head.script:
scwin.pMktactCd;
scwin.pIsuCd;
scwin.pBndApplId;
scwin.pAddIsuAmt;
scwin.pBndListProcsTpCd;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vStripAmtCfm;
scwin.arrPar = new Array();
scwin.sum_StripNsPrtBal_1;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_DtlInfo);
        $c.bns.BnsPanelToGroupBox(pnl_Group);
        $c.bns.BnsPanelToGroupBox(pnl_IsuInfo);
        $c.bns.BnsPanelToGroupBox(pnl_AddInfo);
        $c.bns.BnsPanelToGroupBox(pnl_StripNew);
        $c.bns.BnsPanelToGroupBox(pnl_StripAdd);
        $c.bns.BnsPanelToGroupBox(pnl_MktactAmt);
        // 호출파라미터설정
        scwin.setParam();
        // 저장버튼 숨김여부
        if (scwin.vStripAmtCfm === "View") {
            // 당일 스트립 팝업 시
            btn_Save.hide();
        } else {
            // 처리완료 시
            btn_Save.show("");
        }
        scwin.searchProc();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10002.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_AddAndStrip_OnLoadCompleted
 * @description dts_AddAndStrip 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_AddAndStrip_OnLoadCompleted = function(rowcount) {
    try {
        edt_IsuAmt.RightMargin = 5;
        edt_ListAmt.RightMargin = 5;
        edt_BfchgStripNsprtBal.RightMargin = 5;
        edt_AddIsuAmt.RightMargin = 5;
        edt_StripApplAmt.RightMargin = 5;
        edt_StripParTotAmt.RightMargin = 5;
        edt_UnParTotAmt.RightMargin = 5;
        edt_AfchgIsuAmt.RightMargin = 5;
        edt_AfchgListAmt.RightMargin = 5;
        edt_AfchgStripNsprtBal.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10002.dts_AddAndStrip_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        if (scwin.pMktactCd !== '305') {
            scwin.arrPar[0] = {
                REG_YN: 'Y',
                ADD_LIST_APPL_ID: dts_AddAndStrip.getCellData(1, 'ADD_LIST_APPL_ID'),
                STRIP_APPL_ID: dts_AddAndStrip.getCellData(1, 'STRIP_APPL_ID'),
                ADD_STRIP_APPL_ID: dts_AddAndStrip.getCellData(1, 'ADD_STRIP_APPL_ID'),
                AFCHG_ISU_AMT: dts_AddAndStrip.getCellData(1, 'AFCHG_ISU_AMT'),
                AFCHG_LIST_AMT: dts_AddAndStrip.getCellData(1, 'AFCHG_LIST_AMT'),
                AFCHG_STRIP_NSPRT_BAL: dts_AddAndStrip.getCellData(1, 'AFCHG_STRIP_NSPRT_BAL')
            };
        } else {
            let prt = $c.frame.path("../");
            prt.dts_AddAndStrip.ImportData(dts_AddAndStrip.getRangeJSON(1, dts_AddAndStrip.getRowCount(), false));
            scwin.arrPar[0] = {
                REG_YN: "Y"
            };
        }
        scwin.fn_SetPar(scwin.arrPar);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10002.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10002.btn_Close_onclick" });
    }
};

