 * @name dts_AddAndStrip_OnLoadError
 * @description dts_AddAndStrip 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_AddAndStrip_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10002.dts_AddAndStrip_OnLoadError" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    let prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        const arrPar = new Array();
        scwin.fn_GetPar(scwin.arrPar);
        scwin.vStripAmtCfm = scwin.arrPar[0].VIEW_YN;
        scwin.pMktactCd = scwin.arrPar[0].BND_MKTACT_TP_CD;
        scwin.pIsuCd = scwin.arrPar[0].ISU_CD;
        scwin.pBndApplId = scwin.arrPar[0].BND_APPL_ID;
        scwin.pBndListProcsTpCd = scwin.arrPar[0].BND_LIST_PROCS_TP_CD;
    }
};

/**
 * @method
 * @name searchProc
 * @description 처리완료 시 조회
 * @returns {void}
 * @hidden N
 */
scwin.searchProc = function() {
    let param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.pBndApplId;
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.pBndListProcsTpCd;
    param += "&{P}V_ISU_CD=" + scwin.pIsuCd;
    const dsNm = 'BNS_ADD_AND_STRIP_INTEG';
    let qryId = 'lds.stf.bnschg.select.readAddAndStripInteg';
    if (scwin.vStripAmtCfm !== "View") {
        qryId = 'lds.stf.bnschg.select.readStripRelInfoAddBnd';
    }
    $c.bns.fn_SearchBns('ULDBNS10002.xml', dts_AddAndStrip, dsNm, qryId, param);
};
